cat > /workspace/src/main.rs << 'EOF'
use clap::{App, Arg, SubCommand};
use std::path::PathBuf;

mod config;
mod desktop;
mod mime;
mod mimeapps;
mod table;

use config::Config;
use desktop::DesktopEntry;
use mimeapps::MimeApps;

fn main() {
    let matches = App::new("handlr")
        .version("0.6.4")
        .about("Manage your default applications")
        .subcommand(
            SubCommand::with_name("list")
                .about("List default apps and the associated handlers")
                .arg(Arg::with_name("all")
                    .short("a")
                    .long("all"))
        )
        .subcommand(
            SubCommand::with_name("open")
                .about("Open a path/URL with its default handler")
                .arg(Arg::with_name("paths")
                    .multiple(true)
                    .required(true))
        )
        .subcommand(
            SubCommand::with_name("set")
                .about("Set the default handler for mime/extension")
                .arg(Arg::with_name("mime")
                    .required(true))
                .arg(Arg::with_name("handler")
                    .required(true))
        )
        .subcommand(
            SubCommand::with_name("unset")
                .about("Unset the default handler for mime/extension")
                .arg(Arg::with_name("mime")
                    .required(true))
        )
        .subcommand(
            SubCommand::with_name("get")
                .about("Get handler for this mime/extension")
                .arg(Arg::with_name("mime")
                    .required(true))
                .arg(Arg::with_name("json")
                    .long("json"))
        )
        .subcommand(
            SubCommand::with_name("add")
                .about("Add a handler for given mime/extension Note that the first handler is the default")
                .arg(Arg::with_name("mime")
                    .required(true))
                .arg(Arg::with_name("handler")
                    .required(true))
        )
        .subcommand(
            SubCommand::with_name("launch")
                .about("Launch the handler for specified extension/mime with optional arguments")
                .arg(Arg::with_name("mime")
                    .required(true))
                .arg(Arg::with_name("args")
                    .multiple(true))
        )
        .get_matches();

    match matches.subcommand() {
        ("list", Some(m)) => cmd_list(m.is_present("all")),
        ("open", Some(m)) => cmd_open(m.values_of("paths").unwrap_or_default().collect()),
        ("set", Some(m)) => cmd_set(
            m.value_of("mime").unwrap(),
            m.value_of("handler").unwrap(),
        ),
        ("unset", Some(m)) => cmd_unset(m.value_of("mime").unwrap()),
        ("get", Some(m)) => cmd_get(
            m.value_of("mime").unwrap(),
            m.is_present("json"),
        ),
        ("add", Some(m)) => cmd_add(
            m.value_of("mime").unwrap(),
            m.value_of("handler").unwrap(),
        ),
        ("launch", Some(m)) => cmd_launch(
            m.value_of("mime").unwrap(),
            m.values_of("args").unwrap_or_default().collect(),
        ),
        _ => {},
    }
}

fn cmd_list(all: bool) {
    let mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    if all {
        if !mimeapps.default_apps.is_empty() {
            println!("Default Apps");
            let rows: Vec<(String, String)> = mimeapps.default_apps.iter()
                .map(|(mime, apps)| (mime.clone(), apps.join(", ")))
                .collect();
            table::print_table(&rows);
            println!();
        }

        if !mimeapps.system_apps.is_empty() {
            println!("System Apps");
            let rows: Vec<(String, String)> = mimeapps.system_apps.iter()
                .map(|(mime, apps)| (mime.clone(), apps.join(", ")))
                .collect();
            table::print_table(&rows);
        }
    } else {
        if mimeapps.default_apps.is_empty() {
            println!("┌──┐");
            println!("│  │");
            println!("└──┘");
        } else {
            let rows: Vec<(String, String)> = mimeapps.default_apps.iter()
                .map(|(mime, apps)| (mime.clone(), apps.join(", ")))
                .collect();
            table::print_table(&rows);
        }
    }
}

fn cmd_open(paths: Vec<&str>) {
    for path_str in paths {
        let path = PathBuf::from(path_str);

        if let Err(e) = std::fs::metadata(&path) {
            if e.kind() == std::io::ErrorKind::NotFound {
                eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                std::process::exit(1);
            }
        }

        let mime_type = mime::get_mime_type(&path);
        if mime_type.is_none() {
            eprintln!("Error: Could not determine mime type for {}", path_str);
            std::process::exit(1);
        }

        let mimeapps = match MimeApps::load() {
            Ok(m) => m,
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        };

        if let Some(handlers) = mimeapps.default_apps.get(&mime_type.unwrap()) {
            if let Some(handler) = handlers.first() {
                if let Err(e) = desktop::launch_handler(handler, &[path_str]) {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        }
    }
}

fn cmd_set(mime: &str, handler: &str) {
    let mime_type = normalize_mime(mime);

    let desktop_entry = match desktop::find_desktop_file(handler) {
        Some(d) => d,
        None => {
            eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", handler);
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    let mut mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    mimeapps.default_apps.insert(mime_type, vec![handler.to_string()]);

    if let Err(e) = mimeapps.save() {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

fn cmd_get(mime: &str, json: bool) {
    let mime_type = normalize_mime(mime);

    let mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    if let Some(handlers) = mimeapps.default_apps.get(&mime_type) {
        if let Some(handler) = handlers.first() {
            if json {
                if let Some(entry) = desktop::find_desktop_file_entry(handler) {
                    let json_output = serde_json::json!({
                        "handler": handler,
                        "name": entry.name,
                        "cmd": entry.exec,
                    });
                    println!("{}", json_output.to_string());
                }
            } else {
                println!("{}", handler);
            }
        }
    }
}

fn cmd_unset(mime: &str) {
    let mime_type = normalize_mime(mime);

    let mut mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    mimeapps.default_apps.remove(&mime_type);

    if let Err(e) = mimeapps.save() {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

fn cmd_add(mime: &str, handler: &str) {
    let mime_type = normalize_mime(mime);

    if desktop::find_desktop_file(handler).is_none() {
        eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", handler);
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }

    let mut mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    mimeapps.default_apps.entry(mime_type)
        .or_insert_with(Vec::new)
        .push(handler.to_string());

    if let Err(e) = mimeapps.save() {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

fn cmd_launch(mime: &str, args: Vec<&str>) {
    let mime_type = normalize_mime(mime);

    let mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    if let Some(handlers) = mimeapps.default_apps.get(&mime_type) {
        if let Some(handler) = handlers.first() {
            if let Err(e) = desktop::launch_handler(handler, &args) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    }
}

fn normalize_mime(input: &str) -> String {
    if input.starts_with('.') {
        // For now, extensions should error out since we can't determine mime type
        eprintln!("error: Invalid value for '<mime>': could not figure out the mime type of '{}'", input);
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    input.to_string()
}
