        "txt" | "text" => "text/plain".to_string(),
        "html" | "htm" => "text/html".to_string(),
        "mp4" | "mkv" | "avi" => "video/mp4".to_string(),
        "mp3" | "wav" | "flac" => "audio/mpeg".to_string(),
        _ => return None,
    })
}
