use std::collections::BTreeMap;
use std::path::PathBuf;

pub struct MimeApps {
    pub default_apps: BTreeMap<String, Vec<String>>,
    pub system_apps: BTreeMap<String, Vec<String>>,
}

impl MimeApps {
    pub fn load() -> Result<Self, Box<dyn std::error::Error>> {
        let config_dir = dirs::config_dir()
            .ok_or("Could not determine config directory")?;
        let mimeapps_path = config_dir.join("mimeapps.list");

        let mut mimeapps = MimeApps {
            default_apps: BTreeMap::new(),
            system_apps: BTreeMap::new(),
        };

        if !mimeapps_path.exists() {
            return Ok(mimeapps);
        }

        let content = std::fs::read_to_string(&mimeapps_path)?;
        let mut current_section = "";

        for line in content.lines() {
            let line = line.trim();

            if line.is_empty() || line.starts_with(';') {
                continue;
            }

            if line.starts_with('[') && line.ends_with(']') {
                current_section = line;
                continue;
            }

            if let Some((key, value)) = line.split_once('=') {
                let key = key.trim().to_string();
                let apps: Vec<String> = value.trim()
                    .split(';')
                    .filter(|s| !s.is_empty())
                    .map(|s| s.to_string())
                    .collect();

                match current_section {
                    "[Default Applications]" => {
                        mimeapps.default_apps.insert(key, apps);
                    }
                    "[Added Associations]" => {
                        mimeapps.system_apps.entry(key).or_insert_with(Vec::new).extend(apps);
                    }
                    _ => {}
                }
            }
        }

        Ok(mimeapps)
    }

    pub fn save(&self) -> Result<(), Box<dyn std::error::Error>> {
        let config_dir = dirs::config_dir()
            .ok_or("Could not determine config directory")?;
        let mimeapps_path = config_dir.join("mimeapps.list");

        std::fs::create_dir_all(&config_dir)?;

        let mut content = String::new();
        content.push_str("[Added Associations]\n\n");
        content.push_str("[Default Applications]\n");

        for (mime, apps) in &self.default_apps {
            if !apps.is_empty() {
                content.push_str(&format!("{}={};", mime, apps.join(";")));
                content.push('\n');
            }
        }

        std::fs::write(&mimeapps_path, content)?;
        Ok(())
    }
}
EOF

