pub fn print_table(rows: &[(String, String)]) {
    if rows.is_empty() {
        println!("┌──┐");
        println!("│  │");
        println!("└──┘");
        return;
    }

    // Calculate column widths
    let mut col1_width = 0;
    let mut col2_width = 0;

    for (col1, col2) in rows {
        col1_width = col1_width.max(col1.len());
        col2_width = col2_width.max(col2.len());
    }

    // Print top border
    println!("┌─{}─┬─{}─┐", "─".repeat(col1_width), "─".repeat(col2_width));

    // Print rows
    for (col1, col2) in rows {
        println!("│ {:<width1$} │ {:<width2$} │", 
            col1, col2, 
            width1 = col1_width, 
            width2 = col2_width);
    }

    // Print bottom border
    println!("└─{}─┴─{}─┘", "─".repeat(col1_width), "─".repeat(col2_width));
}
