fn print_help() {
    println!("handlr 0.6.4");
    println!();
    println!("USAGE:");
    println!("    executable <SUBCOMMAND>");
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -V, --version    Prints version information");
