    println!("    open      Open a path/URL with its default handler");
    println!("    set       Set the default handler for mime/extension");
    println!("    unset     Unset the default handler for mime/extension");
    println!("    launch    Launch the handler for specified extension/mime with optional arguments");
    println!("    get       Get handler for this mime/extension");
    println!("    add       Add a handler for given mime/extension Note that the first handler is the default");
}

fn cmd_list(args: &[String]) {
    let mut show_all = false;

    for i in 2..args.len() {
        match args[i].as_str() {
            "-a" | "--all" => show_all = true,
            "-h" | "--help" => {
                println!("executable-list ");
                println!("List default apps and the associated handlers");
                println!();
                println!("USAGE:");
                println!("    executable list [FLAGS]");
                println!();
                println!("FLAGS:");
                println!("    -a, --all        ");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }
            _ => {}
        }
    }

    let mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    if show_all {
        if !mimeapps.default_apps.is_empty() {
            println!("Default Apps");
            let rows: Vec<(String, String)> = mimeapps.default_apps.iter()
                .map(|(mime, apps)| (mime.clone(), apps.join(", ")))
                .collect();
            table::print_table(&rows);
            println!();
        }

        if !mimeapps.system_apps.is_empty() {
            println!("System Apps");
            let rows: Vec<(String, String)> = mimeapps.system_apps.iter()
                .map(|(mime, apps)| (mime.clone(), apps.join(", ")))
                .collect();
            table::print_table(&rows);
        }
    } else {
        if mimeapps.default_apps.is_empty() {
            println!("┌──┐");
            println!("│  │");
            println!("└──┘");
        } else {
            let rows: Vec<(String, String)> = mimeapps.default_apps.iter()
                .map(|(mime, apps)| (mime.clone(), apps.join(", ")))
                .collect();
            table::print_table(&rows);
        }
    }
}

fn cmd_open(args: &[String]) {
    if args.len() < 3 {
        eprintln!("USAGE:");
        eprintln!("    executable open <paths>...");
        process::exit(2);
    }

    for i in 2..args.len() {
        let path_str = &args[i];
        let path = PathBuf::from(path_str);

        if let Err(e) = fs::metadata(&path) {
            if e.kind() == std::io::ErrorKind::NotFound {
                eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                process::exit(1);
            }
