        let mime_type = mime::get_mime_type(&path);
        if mime_type.is_none() {
            eprintln!("Error: Could not determine mime type for {}", path_str);
            process::exit(1);
        }

        let mimeapps = match MimeApps::load() {
            Ok(m) => m,
            Err(e) => {
                eprintln!("Error: {}", e);
                process::exit(1);
