        };

        if let Some(handlers) = mimeapps.default_apps.get(&mime_type.unwrap()) {
            if let Some(handler) = handlers.first() {
                if let Err(e) = desktop::launch_handler(handler, &[path_str]) {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
    }
}

fn cmd_set(args: &[String]) {
