        eprintln!("    executable get [FLAGS] <mime>");
        eprintln!();
        eprintln!("For more information try --help");
        process::exit(2);
    }

    let mut json = false;
    let mut mime_idx = 2;

    for i in 2..args.len() {
        match args[i].as_str() {
            "--json" => json = true,
            "-h" | "--help" => {
                println!("executable-get ");
                println!("Get handler for this mime/extension");
                println!();
                println!("USAGE:");
                println!("    executable get [FLAGS] <mime>");
                println!();
                println!("ARGS:");
                println!("    <mime>    ");
                println!();
                println!("FLAGS:");
                println!("        --json       ");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }
            _ if !args[i].starts_with('-') => {
                mime_idx = i;
                break;
            }
            _ => {}
        }
    }

    let mime = &args[mime_idx];
    let mime_type = normalize_mime(mime);

    let mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    if let Some(handlers) = mimeapps.default_apps.get(&mime_type) {
        if let Some(handler) = handlers.first() {
            if json {
                if let Some(entry) = desktop::find_desktop_file_entry(handler) {
                    let cmd = entry.exec.trim_end_matches(' ');
                    println!("{{\"handler\":\"{}\",\"name\":\"{}\",\"cmd\":\"{}\"}}",
                        handler, entry.name, cmd);
                }
            } else {
                println!("{}", handler);
            }
        }
    }
}

fn cmd_unset(args: &[String]) {
    if args.len() < 3 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <mime>");
