        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    mimeapps.default_apps.entry(mime_type)
        .or_insert_with(Vec::new)
        .push(handler.to_string());

    if let Err(e) = mimeapps.save() {
        eprintln!("Error: {}", e);
        process::exit(1);
    }
}

fn cmd_launch(args: &[String]) {
