        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <mime>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable launch <mime> [args]...");
        eprintln!();
        eprintln!("For more information try --help");
        process::exit(2);
    }

    let mime = &args[2];
    let launch_args: Vec<&str> = args[3..].iter().map(|s| s.as_str()).collect();

    let mime_type = normalize_mime(mime);

    let mimeapps = match MimeApps::load() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    if let Some(handlers) = mimeapps.default_apps.get(&mime_type) {
        if let Some(handler) = handlers.first() {
            if let Err(e) = desktop::launch_handler(handler, &launch_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        }
    }
}

fn normalize_mime(input: &str) -> String {
    if input.starts_with('.') {
        eprintln!("error: Invalid value for '<mime>': could not figure out the mime type of '{}'", input);
        eprintln!();
        eprintln!("For more information try --help");
        process::exit(2);
    }
    input.to_string()
