use std::path::PathBuf;
use std::fs;

pub struct DesktopEntry {
    pub name: String,
    pub exec: String,
    pub mime_types: Vec<String>,
}

pub fn find_desktop_file(name: &str) -> Option<DesktopEntry> {
    let search_paths = get_desktop_search_paths();

    for base_path in search_paths {
        let full_path = base_path.join(name);
        if let Ok(entry) = parse_desktop_file(&full_path) {
            return Some(entry);
        }
    }

    None
}

pub fn find_desktop_file_entry(name: &str) -> Option<DesktopEntry> {
    find_desktop_file(name)
}

pub fn launch_handler(handler: &str, args: &[&str]) -> Result<(), Box<dyn std::error::Error>> {
    let search_paths = get_desktop_search_paths();

    for base_path in search_paths {
        let full_path = base_path.join(handler);
        if full_path.exists() {
            let entry = parse_desktop_file(&full_path)?;
            execute_handler(&entry, args)?;
            return Ok(());
        }
    }

    Err("Handler not found".into())
}

fn get_desktop_search_paths() -> Vec<PathBuf> {
    let mut paths = Vec::new();

    // Add user local applications
    if let Some(home) = get_home_dir() {
        paths.push(home.join(".local/share/applications"));
    }

    // Add system paths
    paths.push(PathBuf::from("/usr/local/share/applications"));
    paths.push(PathBuf::from("/usr/share/applications"));

    // Add XDG data dirs if available
    if let Ok(xdg_dirs) = std::env::var("XDG_DATA_DIRS") {
        for dir in xdg_dirs.split(':') {
            if !dir.is_empty() {
                paths.push(PathBuf::from(dir).join("applications"));
            }
        }
    }

    paths
}

pub fn parse_desktop_file(path: &PathBuf) -> Result<DesktopEntry, Box<dyn std::error::Error>> {
    let content = fs::read_to_string(path)?;
    let mut entry = DesktopEntry {
        name: String::new(),
        exec: String::new(),
        mime_types: Vec::new(),
    };

    for line in content.lines() {
        let line = line.trim();

        if line.starts_with('[') {
            continue;
        }

        if let Some((key, value)) = line.split_once('=') {
            match key.trim() {
                "Name" => entry.name = value.trim().to_string(),
                "Exec" => entry.exec = value.trim().to_string(),
                "MimeType" => {
                    for mime in value.split(';') {
                        let mime = mime.trim();
                        if !mime.is_empty() {
                            entry.mime_types.push(mime.to_string());
                        }
                    }
                }
                _ => {}
            }
        }
    }

    if entry.name.is_empty() || entry.exec.is_empty() {
        return Err("Invalid desktop file".into());
    }

    Ok(entry)
}

fn execute_handler(entry: &DesktopEntry, args: &[&str]) -> Result<(), Box<dyn std::error::Error>> {
    // Parse the Exec field - it may contain %f, %u, %F, %U for files/URLs
    let cmd_parts: Vec<&str> = entry.exec.split_whitespace().collect();

    if cmd_parts.is_empty() {
        return Err("Invalid exec command".into());
    }

    let program = cmd_parts[0];
    let mut command = std::process::Command::new(program);

    // Add any remaining args from the Exec field
    for part in &cmd_parts[1..] {
        // Skip %f, %u, %F, %U placeholders - we'll handle them separately
        if !part.starts_with('%') {
            command.arg(part);
        }
    }

    // Add the arguments passed
    for arg in args {
        command.arg(arg);
    }

    command.env("DBUS_SYSTEM_BUS_ADDRESS", "")
        .spawn()?;

    Ok(())
}

fn get_home_dir() -> Option<PathBuf> {
    if let Ok(home) = std::env::var("HOME") {
        if !home.is_empty() {
            return Some(PathBuf::from(home));
        }
    }
    None
}
